// odometry/src/lib.rs:202-210
/// Trunk position from the anchor: the contact point sits at
/// (`anchor_xy`, 0), the trunk is minus the world-rotated trunk→contact
/// vector away from it.
fn reproject(&mut self, rot: Quat, feet: &[Pose; 2]) { let contact_in_trunk = feet[self.anchor_foot].transform_point(self.anchor_local); let contact = rot.rotate(contact_in_trunk); self.position = [ self.anchor_xy[0] - contact[0], self.anchor_xy[1] - contact[1], -contact[2], ];
} 整个估计器就是这三行。 逐行读： feet[anchor_foot].transform_point(anchor_local) —— 把"接触点在我这只脚里的位置"变成" 接触点在躯干里的位置 "。 这是正向运动学，由 kinematics 完成。 rot.rotate(...) —— 把它从 躯干朝向 转到 世界朝向 。现在 contact 是 " 从躯干指向接触点的向量，用世界的方向表示 "。 position = anchor_xy − contact（X/Y），position[2] = −contact[2] —— 因为接触点的世界位置是 (anchor_xy, 0)，而躯干在 减去那个向量 的地方。 💡 Z 那一行最值得看 ：-contact[2]。 接触点的世界 Z 是 0 （定义如此），所以 position[2] = 0 - contact[2]。 躯干的高度是"接触点相对于躯干有多低"直接取负 —— 不需要任何额外信息。 这就是 §3.2 说的那个"免费拿到的约束"。

