// odometry/src/lib.rs:214-232（节选）
fn lowest_corner(&self, rot: Quat, feet: &[Pose; 2]) -> Option<(usize, [f64; 3], [f64; 2])> { let mut lowest = -SWITCH_MARGIN; let mut best = None; for foot in [LEFT, RIGHT] { for &corner in self.anchors.foot(foot) { let in_world = rot.rotate(feet[foot].transform_point(corner)); let world = [ self.position[0] + in_world[0], // ← 加上躯干自己的位置， self.position[1] + in_world[1], // 才是这个世界里的坐标 self.position[2] + in_world[2], ]; if world[2] < lowest { lowest = world[2]; best = Some((foot, corner, [world[0], world[1]])); } } } best
} 它扫过两只脚的所有候选点，挑出世界里最低的那一个。 注意那个 + self.position：前一步算出的是"相对于躯干"的向量， 加上躯干自己的位置才是 世界坐标 。少了这一步，比较的就是一堆相对高度，没有意义。 返回的是 (哪只脚, 脚坐标系里的点, 它的世界 X/Y) —— 正好是换锚点需要的三样东西。

