// lib.rs:317-329
/// Pitch, roll and yaw of a body → world rotation, degrees.
///
/// **Aerospace order** — yaw about Z, then pitch about the body's Y (nose up positive), then roll
/// about its X (left side up positive) — read off the rotation matrix.
pub fn euler_deg(q: [f32; 4]) -> [f32; 3] { let m = matrix(q); let pitch = (-m[2][0]).clamp(-1.0, 1.0).asin(); let roll = m[2][1].atan2(m[2][2]); let yaw = m[1][0].atan2(m[0][0]); let deg = 180.0 / std::f32::consts::PI; [pitch * deg, roll * deg, yaw * deg] // ← 注意这个顺序
} ⚠️ 返回的是 [pitch, roll, yaw] —— 不是 常见的 [roll, pitch, yaw]， 也 不是 [yaw, pitch, roll]。 这个顺序很容易记反，而记反了不会报错，只是三个数各自装错了轴。 好消息是类型都是 f32，编译器帮不上忙；坏消息是 画面/头部会以"看起来也像那么回事"的方式错 。 两个真实消费者都是 解构 取的，所以顺序是显式的： // padd/src/main.rs:366
let [pitch, roll, yaw] = pad_imu::euler_deg(relative); // imu_view 和 monitor 也是
let [pitch, roll, _] = imu.euler_deg(); 💡 公式本身是标准的 ZYX（航空航天）序 ： R = Rz(yaw)·Ry(pitch)·Rx(roll)，从矩阵里读出来就是那三行。 pitch 那行还有个 .clamp(-1.0, 1.0) —— 因为浮点误差可能让 asin 的输入 差一点点越过 ±1，而 asin(1.0000001) 是 NaN。

