/// Feed `seconds` of a steady reading at 200 Hz.
fn steady(imu: &mut Imu, seconds: f32, accel_g: [f32; 3], gyro_dps: [f32; 3]) { let n = (seconds * 200.0) as u64; let start = imu.last_us.unwrap_or(0); for i in 1..=n { imu.absorb(&one(sample(i, start + i * 5_000, accel_g, gyro_dps))); }
} sample() 那个辅助函数（:461）做的是 反向的换算 ：给它物理单位， 它乘回 4096 / 14247 变回原始整数。 所以整条路径（换算→滤波→欧拉角）都被测到了 ， 而不是绕开换算直接喂物理单位。 而且 steady 接着上次的 last_us 继续，所以连续的 steady 调用像是 一个连续的时间轴 —— 这也是为什么 a_long_gap_is_not_integrated 能手动插一个 3 秒的洞进去。

